def transform(grid):
    # Each color is a damaged collection of rectangular blocks. Use color-wise
    # majority restoration locally: noise is sparse within each panel and sparse outside.
    from collections import Counter
    h,w=len(grid),len(grid[0]); bg=Counter(v for row in grid for v in row).most_common(1)[0][0]
    out=[[bg]*w for _ in range(h)]
    # Search all rectangles, keep dense rectangles at least 2x2; non-overlap panels
    # are ranked by number of matching pixels.
    candidates=[]
    for color in set(v for row in grid for v in row)-{bg}:
      for t in range(h):
       for b in range(t+1,h):
        for l in range(w):
         for r in range(l+1,w):
          area=(b-t+1)*(r-l+1)
          if area<4: continue
          n=sum(grid[y][x]==color for y in range(t,b+1) for x in range(l,r+1))
          if n/area>=.8: candidates.append((n/area,area,n,color,t,b,l,r))
    # greedily use high-quality solid rectangles; output needs preserve all panels.
    candidates.sort(reverse=True)
    occupied=set()
    for density,area,n,color,t,b,l,r in candidates:
      cells={(y,x) for y in range(t,b+1) for x in range(l,r+1)}
      if cells & occupied: continue
      # only choose if rectangle supported by strong density
      for y,x in cells: out[y][x]=color
      occupied |= cells
    return out
